ых патологий","Профилактика сердечно-сосудистых заболеваний","Ранняя диагностика гинекологических проблем и заболеваний молочной железы","Оценка гормонального статуса и функции щитовидной железы","Выявление нарушений обмена веществ и их коррекция","Профилактика онкологических заболеваний"],"preparation":[{"group":"За 24 часа","items":["Воздержитесь от алкоголя и интенсивных физических нагрузок","Не принимайте мочегонные препараты (если не предписано врачом)"]},{"group":"За 12 часов","items":["Прекратите прием пищи","Пейте только воду"]},{"group":"За 8 часов","items":["Воздержитесь от курения","Не пейте кофе и другие стимулирующие напитки"]},{"group":"В день обследования","items":["Возьмите с собой очки или контактные линзы, если вы их носите","Наденьте удобную одежду","Не используйте дезодорант или тальк в области груди и подмышек (для маммографии)","Особые указания","Сообщите врачу о принимаемых лекарствах, добавках и аллергических реакциях","Для получения наиболее точных результатов гинекологических исследований и маммографии рекомендуется проходить обследование в первой половине менструального цикла","При наличии менструации некоторые исследования могут быть перенесены"]}]}$j$::jsonb FROM clinics WHERE slug = 'liv-hospital-istanbul' ON CONFLICT (clinic_id, slug) DO NOTHING;
INSERT INTO checkup_programs (clinic_id, slug, name_ua, name_ru, gender, age_group, price_regular, price_discount, composition, is_specialized, is_active, sort_order, program_type, price_date, currency, details) SELECT id, 'liv-gold-women', 'LIV Gold онкологічний скринінг для жінок', 'LIV GOLD ОНКОЛОГИЧЕСКИЙ СКРИНИНГ для женщин', 'female', NULL, 3000, 3000, $j$[{"group":"Онкология","items":["Консультация онколога","Расширенный анализ онкомаркеров: СА-125, СА 15-3, СА 19-9, РЭА, АФП, НЕ4"]},{"group":"Гинекология и маммология","items":["Консультация гинеколога и маммолога","МРТ и УЗИ органов малого таза, маммография, УЗИ молочных желез, ПАП-тест, тест на ВПЧ"]},{"group":"Гастроэнтерология","items":["Консультация гастроэнтеролога","Колоноскопия (с биопсией при необходимости), гастроскопия (с биопсией при необходимости)","МРТ и УЗИ органов брюшной полости"]},{"group":"Кардиология","items":["Консультация кардиолога","ЭКГ с нагрузкой (Стресс-ЭКГ), эхокардиография"]},{"group":"Пульмонология","items":["Консультация пульмонолога","Цифровой рентген грудной клетки, спирометрия"]},{"group":"Неврология","items":["Консультация невролога","МРТ головного мозга"]},{"group":"Эндокринология","items":["УЗИ щитовидной железы","Анализ гормонов щитовидной железы (ТТГ, Т4 свободный, Т3 свободный)"]},{"group":"Инфекционный скрининг","items":["Анализы на гепатиты B и C, ВИЧ"]},{"group":"Терапия","items":["Общий и биохимический анализ крови, общий анализ мочи","Анализы на витамин D, витамин B12, ферритин, С-реактивный белок (маркер воспаления)","Заключительная консультация терапевта","Подробное заключение о состоянии здоровья и индивидуальные рекомендации"]}]$j$::jsonb, false, true, 1, 'clinic', '2026-11-16', 'USD', $j${"summary":"Комплексная онкодиагностика для вашего спокойствия и здоровья","duration":"2-3 дня","description":["Программа \"LIV GOLD ОНКОЛОГИЧЕСКИЙ СКРИНИНГ для женщин\" разработана для всесторонней диагностики онкологических заболеваний на ранних стадиях. Она включает в себя самые современные методы обследования, позволяющие выявить даже минимальные изменения в организме."],"goals":["Ранняя диагностика онкологических заболеваний","Выявление предраковых состояний","Оценка общего состояния здоровья","Определение индивидуальных факторов риска","Разработка персонализированного плана профилактики"],"preparation":[{"group":"За 3 дня","items":["Исключите из рациона продукты, вызывающие метеоризм (бобовые, капусту, свежие фрукты)","Прекратите прием препаратов железа и активированного угля"]},{"group":"За 24 часа","items":["Воздержитесь от алкоголя и интенсивных физических нагрузок","Не принимайте слабительные препараты"]},{"group":"За 12 часов","items":["Прекратите прием пищи","Пейте только воду"]},{"group":"За 8 часов","items":["Воздержитесь от курения","Не пейте воду"]},{"group":"В день обследования","items":["Возьмите с собой все имеющиеся медицинские документы и результаты предыдущих обследований","Наденьте удобную одежду, легко снимающуюся для обследований","Не используйте дезодорант или тальк в области груди и подмышек (для маммографии)"]},{"group":"Особые указания","items":["Сообщите врачу о принимаемых лекарствах, добавках и аллергических реакциях","Для получения наиболее точных результатов гинекологических исследований рекомендуется проходить обследование в первой половине менструального цикла","При наличии менструации некоторые исследования могут быть перенесены","Для колоноскопии потребуется специальная подготовка, о которой вас проинформируют дополнительно"]}]}$j$::jsonb FROM clinics WHERE slug = 'liv-hospital-istanbul' ON CONFLICT (clinic_id, slug) DO NOTHING;
