следования наденьте удобную одежду."]},{"group":"Особые указания","items":["Сообщите врачу о принимаемых лекарствах, добавках и аллергических реакциях.","Для УЗИ предстательной железы может потребоваться наполненный мочевой пузырь (уточните у администраторов клиники)."]}]}$j$::jsonb FROM clinics WHERE slug = 'liv-hospital-istanbul' ON CONFLICT (clinic_id, slug) DO NOTHING;
INSERT INTO checkup_programs (clinic_id, slug, name_ua, name_ru, gender, age_group, price_regular, price_discount, composition, is_specialized, is_active, sort_order, program_type, price_date, currency, details) SELECT id, 'liv-silver-women', 'LIV Silver онкологічний скринінг для жінок', 'LIV SILVER ОНКОЛОГИЧЕСКИЙ СКРИНИНГ для женщин', 'female', NULL, 2200, 2200, $j$[{"group":"Онкология","items":["Консультация онколога","Анализ онкомаркеров: СА-125, СА 15-3, СА 19-9, РЭА, АФП"]},{"group":"Гинекология и маммология","items":["Консультация гинеколога и маммолога","МРТ и УЗИ органов малого таза, маммография, УЗИ молочных желез, ПАП-тест"]},{"group":"Гастроэнтерология","items":["Консультация гастроэнтеролога","МРТ и УЗИ органов брюшной полости"]},{"group":"Кардиология","items":["Консультация кардиолога","ЭКГ с нагрузкой (Стресс-ЭКГ),","эхокардиография"]},{"group":"Пульмонология","items":["Консультация пульмонолога","Цифровой рентген грудной клетки"]},{"group":"Эндокринология","items":["УЗИ щитовидной железы","Анализ гормонов щитовидной железы (ТТГ, Т4 свободный, тиреоглобулин)"]},{"group":"Инфекционный скрининг","items":["Анализы на гепатиты B и C, ВИЧ"]},{"group":"Терапия","items":["МРТ головного мозга","Общий и биохимический анализ крови, общий анализ мочи","Анализы на витамин D, витамин B12, ферритин","Заключительная консультация терапевта","Подробное заключение о состоянии здоровья и индивидуальные рекомендации"]}]$j$::jsonb, false, true, 6, 'clinic', '2026-11-16', 'USD', $j${"summary":"Эффективная онкодиагностика для активных женщин","duration":"2 дня","description":["Программа \"LIV SILVER ОНКОЛОГИЧЕСКИЙ СКРИНИНГ для женщин\" представляет собой оптимальное сочетание ключевых диагностических процедур, направленных на раннее выявление наиболее распространенных онкологических заболеваний у женщин. Она разработана с учетом современных медицинских стандартов и включает в себя комплекс высокоточных исследований."],"goals":["Своевременное обнаружение онкологических заболе